package fixture

import (
	"bytes"
	"testing"

	"github.com/fieldcut/fieldcut/internal/base"
	"github.com/fieldcut/fieldcut/internal/ingest"
)

func TestGeneratedManifestConsistency(t *testing.T) {
	t.Parallel()
	for _, codec := range []ingest.Codec{ingest.CodecH264, ingest.CodecH265, ingest.CodecAV1} {
		codec := codec
		t.Run(string(codec), func(t *testing.T) {
			bs := Generate(Params{Camera: "c", Rendition: "r", Codec: codec,
				Units: 240, TimeBase: base.ClockRate, Seed: 1})
			// Every manifest range must land inside the generated bytes.
			if err := bs.Manifest.Validate(int64(len(bs.Data))); err != nil {
				t.Fatalf("%s manifest invalid: %v", codec, err)
			}
			// Offsets are strictly increasing and cover contiguous units.
			for i := 1; i < len(bs.Manifest.Entries); i++ {
				prev := bs.Manifest.Entries[i-1]
				cur := bs.Manifest.Entries[i]
				if cur.Offset != prev.Offset+int64(prev.Length) {
					t.Fatalf("%s: non-contiguous unit at %d", codec, i)
				}
			}
		})
	}
}

func TestTSVManifestRoundTrips(t *testing.T) {
	t.Parallel()
	bs := Generate(Params{Camera: "cam", Rendition: "rend", Codec: ingest.CodecAV1,
		Units: 30, TimeBase: base.ClockRate, Seed: 2})
	tsv := ManifestTSV(bs.Manifest)
	parsed, err := ingest.ParseTSVManifest(
		bytes.NewReader(tsv), int64(len(bs.Data)))
	if err != nil {
		t.Fatal(err)
	}
	if len(parsed.Entries) != len(bs.Manifest.Entries) {
		t.Fatalf("tsv row count %d != %d", len(parsed.Entries), len(bs.Manifest.Entries))
	}
	for i := range parsed.Entries {
		if parsed.Entries[i].Offset != bs.Manifest.Entries[i].Offset ||
			parsed.Entries[i].Keyframe != bs.Manifest.Entries[i].Keyframe {
			t.Fatalf("tsv row %d did not round-trip", i)
		}
	}
}
